#include <iostream>
#include <string>
#include <vector>

// The solution file defines this struct identically; the layout must match.
struct MinStack
{
    std::vector<int> values;
    std::vector<int> mins;
};

void Push(MinStack& s, int value);
void Pop(MinStack& s);
int Min(const MinStack& s);

int main()
{
    int n;
    while (std::cin >> n)
    {
        MinStack s;
        bool first = true;
        for (int i = 0; i < n; i++)
        {
            std::string op;
            std::cin >> op;
            if (op == "push")
            {
                int v;
                std::cin >> v;
                Push(s, v);
            }
            else if (op == "pop")
            {
                Pop(s);
            }
            else
            {
                if (!first) { std::cout << " "; }
                first = false;
                std::cout << Min(s);
            }
        }
        std::cout << "\n";
    }
    return 0;
}

