"""Random valid operation sequences (never pop or query when empty), with a
small value range so equal minima are common."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    ops = []
    depth = 0
    queries = 0
    for _ in range(rng.randint(6, 16)):
        choice = rng.random()
        if depth == 0 or choice < 0.45:
            ops.append("push %d" % rng.randint(-5, 5))
            depth += 1
        elif choice < 0.7:
            ops.append("pop")
            depth -= 1
        else:
            ops.append("min")
            queries += 1
    if not queries:
        ops.append("min")
    return {"name": "%d operations #%d" % (len(ops), index),
            "stdin": "%d\n%s\n" % (len(ops), "\n".join(ops))}
